import{z as s,x as l,o as A,c as C,q as r,j as o,D as a,d as e,s as n,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"回测性能优化","description":"","frontmatter":{"title":"回测性能优化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-backtest-perf.md","filePath":"quant/de-backtest-perf.md","lastUpdated":1791063341000}'),d={name:"quant/de-backtest-perf.md"};function p(h,E,f,u,D,c){const B=l("Mermaid");return A(),C("div",null,[E[2]||(E[2]=r('<h1 id="回测性能优化" tabindex="-1">回测性能优化 <a class="header-anchor" href="#回测性能优化" aria-label="Permalink to &quot;回测性能优化&quot;">​</a></h1><div class="epigraph"><p>过早优化是万恶之源；但在回测里，优化晚了照样是恶——省下的每一小时都被换成多扫一轮参数，泄漏跟着速度一起涨。</p><footer>—— 据 Knuth, Structured Programming with go to Statement, 1974；与站内回测向量化的合法性判据整理</footer></div><p><a href="/quant/de-distributed-backtest">上一课</a>把回测摊到集群，前提是每个叶子任务别太慢；本课回到单任务：一个回测跑十小时，集群再大也白搭。性能优化的对象是算法复杂度与数据访问，方法来自普通工程；特殊之处在约束——每一处「提速」都可能顺手改变信息集，把泄漏当加速。判据沿用<a href="/quant/backtest-vectorization">回测向量化</a>：优化前后信息集必须逐日相同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>性能问题先诊断再动手，症状分三类。<span class="marginnote">术语翻译：profiler（性能剖析器）就是给代码记时间账的工具——它告诉你十小时里每个函数各花了多久。没有它就优化，等于不做体检就开药：你以为病在计算，其实是八小时都花在读盘上，改哪行代码都没用。</span>IO 密集：时间花在扫描与反序列化，十小时里八小时在读 tick——解法在数据侧，选型课的列存与分区裁剪在这里兑现。计算密集：时间花在逐行循环与重复计算——解法在算法侧。无谓密集：时间花在重算不变的东西——解法在物化侧。不区分就优化的典型下场：把最热的查询路径重写成更快的逐行循环，而时间根本不在那里。诊断工具就是 profiler：按函数、按数据段计时，先找到那八小时。</p><h3 id="三类优化各有边界" tabindex="-1">三类优化各有边界 <a class="header-anchor" href="#三类优化各有边界" aria-label="Permalink to &quot;三类优化各有边界&quot;">​</a></h3><p>数据侧：列式读取按需取列（<a href="/quant/apache-arrow">Apache Arrow</a> 的零拷贝列式内存让多引擎共享同一份缓冲），分区裁剪限制日期段，特征预物化成只读快照——但物化的统计量必须只用截至当日的数据，全样本均值是泄漏不是加速。算法侧：把逐行 Python 循环换成数组运算或即时编译，把滚动统计换成增量更新；窗口语义要与原实现逐点对齐。物化侧：同一实验网格共享的特征段算一次，按（数据版本、日期段）键控缓存，与<a href="/quant/fml-feature-store-deep">特征存储的深入</a>的快照口径一致。</p><p><span class="marginnote">滚动均值与方差的增量更新把窗口代价从 \\(O(w)\\) 降到 \\(O(1)\\)：\\(\\bar x_t=\\bar x_{t-1}+(x_t-x_{t-w})/w\\)，方差用同构的平方和递推。十年日频、一年窗口，重算与增量差约两百倍——够把一次过夜批变成一次交互。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优化流程四步，每步带验收。<strong>一，profile 定位</strong>：分 IO、计算、物化三类归因，记录火焰图入实验档案。<strong>二，单点替换</strong>：每轮只改一处，替换前后对同一小样本跑逐日对账——净值、持仓、成交三张表逐日 diff，超容差即回滚；这与特征店的影子对比同构，只是压到了日粒度。<strong>三，等价性分级</strong>：数值完全一致为强等价；浮点求和顺序改变导致的舍入差为弱等价，容差要钉死并写进引擎文档，因为弱等价的回测跨机器不可精确复现，会污染上一课的结果登记。<strong>四，回归入册</strong>：把对账脚本留在持续集成里，引擎或缓存任何变更自动重跑。</p>',10)),(A(),o(i,null,{default:a(()=>[n(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22profile%EF%BC%9AIO%20%2F%20%E8%AE%A1%E7%AE%97%20%2F%20%E7%89%A9%E5%8C%96%E5%BD%92%E5%9B%A0%22%5D%20--%3E%20SEL%7B%22%E6%9C%80%E5%A4%A7%E5%A4%B4%E5%9C%A8%E5%93%AA%E4%B8%80%E7%B1%BB%22%7D%0A%20%20SEL%20--%3E%7CIO%7C%20D%5B%22%E5%88%97%E8%A3%81%E5%89%AA%E3%80%81%E5%88%86%E5%8C%BA%E8%A3%81%E5%89%AA%E3%80%81%E9%A2%84%E7%89%A9%E5%8C%96%22%5D%0A%20%20SEL%20--%3E%7C%E8%AE%A1%E7%AE%97%7C%20C%5B%22%E6%95%B0%E7%BB%84%E5%8C%96%E3%80%81%E5%A2%9E%E9%87%8F%E6%9B%B4%E6%96%B0%E3%80%81%E5%8D%B3%E6%97%B6%E7%BC%96%E8%AF%91%22%5D%0A%20%20SEL%20--%3E%7C%E7%89%A9%E5%8C%96%7C%20M%5B%22%E5%85%B1%E4%BA%AB%E7%BC%93%E5%AD%98%EF%BC%9A%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%20%2B%20%E6%97%A5%E6%9C%9F%E6%AE%B5%22%5D%0A%20%20D%20--%3E%20EQ%5B%22%E9%80%90%E6%97%A5%E5%AF%B9%E8%B4%A6%EF%BC%9A%E5%87%80%E5%80%BC%E3%80%81%E6%8C%81%E4%BB%93%E3%80%81%E6%88%90%E4%BA%A4%22%5D%0A%20%20C%20--%3E%20EQ%0A%20%20M%20--%3E%20EQ%0A%20%20EQ%20--%3E%7C%22%E5%BC%BA%E7%AD%89%E4%BB%B7%E6%88%96%E9%92%89%E6%AD%BB%E5%AE%B9%E5%B7%AE%22%7C%20KEEP%5B%22%E7%BA%B3%E5%85%A5%E5%BC%95%E6%93%8E%EF%BC%8C%E5%9B%9E%E5%BD%92%E5%85%A5%E5%86%8C%22%5D%0A%20%20EQ%20--%3E%7C%22%E8%B6%85%E5%AE%B9%E5%B7%AE%22%7C%20RB%5B%22%E5%9B%9E%E6%BB%9A%EF%BC%9A%E6%B3%84%E6%BC%8F%E5%AB%8C%E7%96%91%E4%BC%98%E5%85%88%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"性能与正确性在这里共用一条机制：回测的成本结构与信息集结构是同一张图。逐日对账能同时抓住两类错——泄漏与数值漂移——因为两者都表现为「提速后某天的持仓变了」。这也解释了为什么优化顺序应从数据侧开始：列裁剪与分区裁剪不触碰计算语义，是无风险的第一段收益；算法替换（增量更新、数组化）都在改写计算的组合方式，风险随深度上升。缓存把风险移到键上：键少一个数据版本，就制造一次「修了 bug 结果不变」的事故——键的完整性是缓存唯一要守的约束。性能收益的归宿在研究侧：单任务从十小时到十分钟，走窗验证才能从「季度一次」变成「每次改动」，协议的严格性与速度是同一枚硬币。",-1)),(A(),o(i,null,{default:a(()=>[n(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22%E7%AC%AC%E4%B8%80%E7%BA%A7%3A%20%E5%88%97%E8%A3%81%E5%89%AA%20%2F%20%E5%88%86%E5%8C%BA%E8%A3%81%E5%89%AA%22%5D%20--%3E%20R0%5B%22%E4%B8%8D%E7%A2%B0%E8%AE%A1%E7%AE%97%E8%AF%AD%E4%B9%89%2C%20%E9%A3%8E%E9%99%A9%E6%9C%80%E4%BD%8E%22%5D%0A%20%20R0%20--%3E%20L1%5B%22%E7%AC%AC%E4%BA%8C%E7%BA%A7%3A%20%E5%85%B1%E4%BA%AB%E7%BC%93%E5%AD%98%2C%20%E9%94%AE%20%3D%20%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%20%2B%20%E6%97%A5%E6%9C%9F%E6%AE%B5%22%5D%0A%20%20L1%20--%3E%20R1%5B%22%E9%A3%8E%E9%99%A9%E7%A7%BB%E5%88%B0%E9%94%AE%E7%9A%84%E5%AE%8C%E6%95%B4%E6%80%A7%22%5D%0A%20%20R1%20--%3E%20L2%5B%22%E7%AC%AC%E4%B8%89%E7%BA%A7%3A%20%E5%A2%9E%E9%87%8F%E6%9B%B4%E6%96%B0%20%2F%20%E6%95%B0%E7%BB%84%E5%8C%96%20%2F%20%E5%8D%B3%E6%97%B6%E7%BC%96%E8%AF%91%22%5D%0A%20%20L2%20--%3E%20R2%5B%22%E6%94%B9%E5%86%99%E8%AE%A1%E7%AE%97%E7%BB%84%E5%90%88%E6%96%B9%E5%BC%8F%2C%20%E6%B5%AE%E7%82%B9%E9%87%8D%E6%8E%92%22%5D%0A%20%20R2%20--%3E%20L3%5B%22%E7%AC%AC%E5%9B%9B%E7%BA%A7%3A%20%E6%94%B9%E4%BF%A1%E5%8F%B7%E8%AE%BE%E8%AE%A1%E5%8E%BB%E6%8E%89%E7%9B%98%E4%B8%AD%E8%B7%AF%E5%BE%84%22%5D%0A%20%20L3%20--%3E%20R3%5B%22%E7%AD%89%E4%BA%8E%E9%87%8D%E5%86%99%2C%20%E6%B3%84%E6%BC%8F%E5%AB%8C%E7%96%91%E6%9C%80%E5%A4%A7%22%5D%0A%20%20R2%20--%3E%20EQ%5B%22%E5%BF%85%E9%A1%BB%E9%80%90%E6%97%A5%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20R3%20--%3E%20EQ%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不优化「不该存在的计算」：若一个信号本可向量化却依赖盘中路径，先回看<a href="/quant/backtest-vectorization">回测向量化</a>的判据改设计，再谈速度。<span class="marginnote">常见误区：初学者容易以为「优化」只是让代码跑得更快、结果一模一样。实际上把逐行求和换成数组求和，浮点加法的顺序变了，净值末几位小数可能差 1e-12——这不是 bug，是弱等价。真正危险的是把这种「结果有小差」当成理所当然而不设容差：泄漏也表现为小差，两者必须靠逐日对账区分。</span>即时编译与向量化带来的浮点重排不可避免，强等价常达不到——容差是工程决策，不是悄悄吸收的误差。分布式加速见上一课；引擎内的事件循环与成交模拟怎么写快，属于下一门回测框架课程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先 profile 再动手：IO、计算、物化三类归因，最大头优先。</li><li>数据侧优化无风险优先做；算法替换必须过逐日对账。</li><li>等价性分级：强等价、钉死容差的弱等价；超容差按泄漏嫌疑处理。</li><li>缓存键必须含数据版本与日期段，缺一项就制造静默事故。</li><li>性能的归宿是研究节奏：单任务快十倍，走窗才可能常态化。</li><li>出处：Knuth, 1974；站内<a href="/quant/backtest-vectorization">回测向量化</a>、<a href="/quant/apache-arrow">Apache Arrow</a>与<a href="/quant/fml-feature-store-deep">特征存储的深入</a>各课。</li></ul>',4))])}const b=s(d,[["render",p]]);export{_ as __pageData,b as default};
